"""Check real macOS codecs with the exact arguments generated by the app."""
import json
import math
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import unittest
import wave

from js_engine import evaluate

ROOT = Path(__file__).resolve().parents[1]


@unittest.skipUnless(sys.platform == "darwin", "afconvert/Core Audio requires a Mac")
class AudioConversionTests(unittest.TestCase):
    def test_real_m4a_and_wav_profiles_are_decodable(self):
        source = (ROOT / "src/kasholkaTTS.js").read_text(encoding="utf-8")
        output = ROOT / "build"
        output.mkdir(exist_ok=True)
        with tempfile.TemporaryDirectory(dir=output, prefix="audio test ") as directory:
            original = Path(directory) / "source ' tone.wav"
            # Like speech voices, this source is mono and below 44.1 kHz.
            samples = [int(8000 * math.sin(2 * math.pi * 440 * n / 22050)) for n in range(11025)]
            with wave.open(str(original), "wb") as audio:
                audio.setparams((1, 2, 22050, 0, "NONE", "not compressed"))
                audio.writeframes(struct.pack("<" + "h" * len(samples), *samples))
            for fmt, quality in [("m4a", 64000), ("m4a", 128000), ("m4a", 192000), ("wav", 16), ("wav", 24)]:
                with self.subTest(format=fmt, quality=quality):
                    destination = Path(directory) / f"result {quality}.{fmt}"
                    values = json.dumps([fmt, quality, str(original), str(destination)])
                    script = "(function () {\n" + source + "\nreturn JSON.stringify(audioConversionArguments.apply(null, " + values + "));\n}());"
                    args = json.loads(evaluate(script))
                    result = subprocess.run(["/usr/bin/afconvert", *args], capture_output=True, text=True, timeout=30)
                    self.assertEqual(result.returncode, 0, result.stderr)
                    self.assertGreater(destination.stat().st_size, 64)
                    header = destination.read_bytes()[:12]
                    if fmt == "m4a":
                        self.assertEqual(header[4:8], b"ftyp")
                        decoded = Path(directory) / "decoded.wav"
                        if decoded.exists():
                            decoded.unlink()
                        result = subprocess.run(["/usr/bin/afconvert", "-f", "WAVE", "-d", "LEI16", str(destination), str(decoded)],
                                                capture_output=True, text=True, timeout=30)
                        self.assertEqual(result.returncode, 0, result.stderr)
                    else:
                        self.assertEqual(header[:4], b"RIFF")
                        self.assertEqual(header[8:12], b"WAVE")
                        decoded = destination
                    with wave.open(str(decoded), "rb") as audio:
                        self.assertEqual(audio.getnchannels(), 1)
                        self.assertAlmostEqual(audio.getnframes() / audio.getframerate(), 0.5, delta=0.15)
                        self.assertEqual(audio.getsampwidth(), quality // 8 if fmt == "wav" else 2)
                        self.assertTrue(any(audio.readframes(audio.getnframes())))
